/* ------------------------------------------------------------ 2. fondo: cuadrícula + resplandores */
body.gds {
  min-height: 100vh;
  background:
    radial-gradient(40% 40% at 88% 4%, var(--uv-glow-violet), transparent 70%),
    radial-gradient(35% 30% at 6% 30%, var(--uv-glow-amber), transparent 70%),
    linear-gradient(var(--uv-grid) 1px, transparent 1px) 0 0 / 100% var(--uv-grid-step),
    linear-gradient(90deg, var(--uv-grid) 1px, transparent 1px) 0 0 / var(--uv-grid-step) 100%,
    var(--uv-bg);
  background-attachment: fixed;
}

ops.text:
/* ------------------------------------------------------------ 2. fondo: cuadrícula + resplandores */
/* 1.6.0 (scroll fluido): antes era el fondo del body con background-attachment: fixed, y eso obliga
   al navegador a repintar toda la pantalla en cada paso del scroll (los «saltitos»). Ahora el
   escenario es una capa fija propia, detrás de todo: se pinta una vez y al bajar solo se mueve el
   contenido. Se ve igual (los porcentajes siguen siendo de la ventana). */
body.gds { min-height: 100vh; background: var(--uv-bg); }
body.gds::before {
  content: ""; position: fixed; inset: 0; z-index: -2; pointer-events: none;
  background:
    radial-gradient(40% 40% at 88% 4%, var(--uv-glow-violet), transparent 70%),
    radial-gradient(35% 30% at 6% 30%, var(--uv-glow-amber), transparent 70%),
    linear-gradient(var(--uv-grid) 1px, transparent 1px) 0 0 / 100% var(--uv-grid-step),
    linear-gradient(90deg, var(--uv-grid) 1px, transparent 1px) 0 0 / var(--uv-grid-step) 100%;
  transform: translateZ(0);
}

